#include "sblr_sec_drop_user_runtime.hpp"
#include <cstring>
namespace scratchbird::engine::sblr { namespace {void w16(std::vector<uint8_t>&b,size_t p,uint16_t v){b[p]=v;b[p+1]=v>>8;}void w32(std::vector<uint8_t>&b,size_t p,uint32_t v){for(int i=0;i<4;i++)b[p+i]=v>>(8*i);}void w64(std::vector<uint8_t>&b,size_t p,uint64_t v){for(int i=0;i<8;i++)b[p+i]=v>>(8*i);}uint64_t r64(const uint8_t*p,size_t n){uint64_t v=0;for(int i=0;i<8;i++)v|=uint64_t(p[n+i])<<(8*i);return v;}void cp(std::vector<uint8_t>&b,size_t p,const void*x,size_t n){std::memcpy(b.data()+p,x,n);}bool h(const uint8_t*p,size_t n,const char*m,size_t z,std::string*d){if(!p||n!=z||std::memcmp(p,m,4)){if(d)*d="invalid SDU frame";return false;}return true;}}
std::vector<uint8_t> EncodeSblrSecDropUserRequestV1(const SblrSecDropUserRequestV1&v){std::vector<uint8_t>b(64);cp(b,0,"SDUQ",4);w16(b,4,1);w16(b,6,64);w32(b,8,64);cp(b,16,v.receipt.data(),16);w64(b,32,v.occurrence);return b;}bool DecodeSblrSecDropUserRequestV1(const uint8_t*p,size_t n,SblrSecDropUserRequestV1*o,std::string*d){if(!o||!h(p,n,"SDUQ",64,d))return false;std::memcpy(o->receipt.data(),p+16,16);o->occurrence=r64(p,32);return o->occurrence!=0;}
std::vector<uint8_t> EncodeSblrSecDropUserDescriptorV1(const SblrSecDropUserDescriptorV1&v,bool op){std::vector<uint8_t>b(128);cp(b,0,op?"SDUO":"SDUD",4);w16(b,4,1);w16(b,6,128);w32(b,8,128);cp(b,16,v.user_uuid.data(),16);w64(b,32,v.expected_generation);w64(b,40,v.catalog_generation);w64(b,48,v.security_generation);w64(b,56,v.availability);cp(b,64,v.descriptor_evidence.data(),16);return b;}bool DecodeSblrSecDropUserDescriptorV1(const uint8_t*p,size_t n,SblrSecDropUserDescriptorV1*o,std::string*d,bool op){if(!o||!h(p,n,op?"SDUO":"SDUD",128,d))return false;std::memcpy(o->user_uuid.data(),p+16,16);o->expected_generation=r64(p,32);o->catalog_generation=r64(p,40);o->security_generation=r64(p,48);o->availability=r64(p,56);std::memcpy(o->descriptor_evidence.data(),p+64,16);return o->availability!=0;}
std::vector<uint8_t> EncodeSblrSecDropUserResultV1(const SblrSecDropUserResultV1&v){std::vector<uint8_t>b(128);cp(b,0,"SDUR",4);w16(b,4,1);w16(b,6,128);w32(b,8,128);b[16]=v.status;b[17]=v.publication_barrier;cp(b,24,v.user_uuid.data(),16);w64(b,40,v.generation);w64(b,48,v.security_generation);w64(b,56,v.availability);cp(b,64,v.effect_evidence.data(),32);return b;}bool DecodeSblrSecDropUserResultV1(const uint8_t*p,size_t n,SblrSecDropUserResultV1*o,std::string*d){if(!o||!h(p,n,"SDUR",128,d))return false;o->status=p[16];o->publication_barrier=p[17];std::memcpy(o->user_uuid.data(),p+24,16);o->generation=r64(p,40);o->security_generation=r64(p,48);o->availability=r64(p,56);std::memcpy(o->effect_evidence.data(),p+64,32);return true;}}
